parameters.jsCode:
// Measure response times for critical endpoints
const endpoints = [
  '/api/health',
  '/api/health/kpis',
  '/api/kpis'
];

const baseUrl = 'https://rentokil-bi-git-alpha-test-clasaks-projects.vercel.app';
const results = [];

for (const endpoint of endpoints) {
  const start = Date.now();
  let statusCode = 0;
  let isError = false;

  try {
    const response = await fetch(baseUrl + endpoint, {
      method: 'GET',
      headers: { 'Accept': 'application/json' }
    });
    statusCode = response.status;
    isError = statusCode >= 400;
  } catch (error) {
    statusCode = 0;
    isError = true;
  }

  const responseTime = Date.now() - start;

  results.push({
    endpoint,
    method: 'GET',
    response_time_ms: responseTime,
    status_code: statusCode,
    is_error: isError
  });
}

// Calculate summary stats
const avgResponseTime = Math.round(results.reduce((sum, r) => sum + r.response_time_ms, 0) / results.length);
const maxResponseTime = Math.max(...results.map(r => r.response_time_ms));
const errors = results.filter(r => r.is_error).length;

// Check SLA thresholds
const p95Target = 2000;
const slaBreaches = results.filter(r => r.response_time_ms > p95Target);

return [{
  json: {
    results,
    summary: {
      avg_response_ms: avgResponseTime,
      max_response_ms: maxResponseTime,
      error_count: errors,
      total_checks: results.length
    },
    hasSLABreach: slaBreaches.length > 0,
    slaBreaches: slaBreaches.map(r => `${r.endpoint}: ${r.response_time_ms}ms`),
    timestamp: new Date().toISOString()
  }
}];

// Split results for individual inserts
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  if (data && data.results && Array.isArray(data.results)) {
    for (const metric of data.results) {
      results.push({ json: metric });
    }
  }
}

return results.length > 0 ? results : [{ json: { error: 'No metrics to process' } }];

